import { Provider } from '@ethersproject/abstract-provider'
import { Contract, BigNumber } from 'ethers'

import { L1Provider, ProviderLike } from './interfaces'
import { toProvider } from './utils'
import { getContractInterface } from './utils/contract-defs'

/**
 * Returns a Contract object for the Contract, default is L1MessageQueueWithGasPriceOracle.
 *
 * @param provider Provider to attach the contract to.
 * @returns Contract object for the Contract, default is L1MessageQueueWithGasPriceOracle.
 */
const connectGasPriceOracle = (provider: ProviderLike, contractAddress?: string, contractName?: string): Contract => {
  return new Contract(
    contractAddress,
    getContractInterface(contractName || 'L1MessageQueueWithGasPriceOracle'),
    toProvider(provider)
  )
}

/**
 * Gets the current L1 gas price as seen on L2.
 *
 * @param l1Provider L1 provider to query the L1 gas price from.
 * @returns Current L1 gas price as seen on L1.
 */
export const estimateCrossDomainMessageFee = async (
  l1Provider: ProviderLike,
  contractAddress: string,
  contractName?: string,
): Promise<BigNumber> => {
  const gpo = connectGasPriceOracle(l1Provider, contractAddress, contractName)
  return gpo.l2BaseFee()
}

/**
 * Determines if a given Provider is an L1Provider.  Will coerce type
 * if true
 *
 * @param provider The provider to check
 * @returns Boolean
 */
export const isL1Provider = <TProvider extends Provider>(
  provider: TProvider
): provider is L1Provider<TProvider> => {
  return Boolean((provider as L1Provider<TProvider>)._isL1Provider)
}
